            Ok(bound) => bound,
            Err(bind_err) => {
                match bind_err.raw_os_error() {
                    Some(code) => {
                        let addr_in_use = code == libc::EADDRINUSE;
                        let denied = code == libc::EACCES;
                        let missing = code == libc::ENOENT;
                        let not_dir = code == libc::ENOTDIR;
                        let invalid = code == libc::EINVAL;
                        let too_long = code == libc::ENAMETOOLONG;
                        let unavailable = code == libc::EADDRNOTAVAIL;
                        let looping = code == libc::ELOOP;
                        if addr_in_use {
                            return Err(bind_err);
                        }
                        if denied {
                            return Err(bind_err);
                        }
                        if missing {
                            return Err(bind_err);
                        }
                        if not_dir {
                            return Err(bind_err);
                        }
                        if invalid {
                            return Err(bind_err);
                        }
                        if too_long {
                            return Err(bind_err);
                        }
                        if unavailable {
                            return Err(bind_err);
                        }
                        if looping {
                            return Err(bind_err);
